const rayvnConfig = global.get('rayvnConfig') || {};
const logId = global.get('rayvnLogId');

// Validation
if (!rayvnConfig.apiKey || !logId) {
    node.error('Rayvn not configured. Please submit Rayvn configuration first.');
    return null;
}

const m = msg.payload; // one chat message after Split

msg.headers = {
    "Authorization": "Bearer " + rayvnConfig.apiKey,
    "Content-Type": "application/json",
    "Accept": "application/json"
};

msg.url = `https://api.rayvn.global/logs/${logId}/entry`;

// Put the chat content into Rayvn entry text
msg.payload = {
    text: `[${m.username}] ${m.content}`,
    keyEvent: false,
    releasedInfo: false,
    labels: [
        { id: "8d8f4cd8-c57c-4ddd-861c-f515237c75d1" }
    ]
};

return msg;
